<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/classes/GreenPortalDatabase.php';
require_once dirname(__DIR__) . '/classes/UsuarioSessao.php';
require_once dirname(__DIR__) . '/classes/PermissaoTransacao.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
if (empty($_SESSION['autenticado']) || empty($_SESSION['tenant']['banco_dados'])) { http_response_code(401); exit('Sessão expirada.'); }
$env = GreenPortalDatabase::env(); $pdo = GreenPortalDatabase::connect($env, (string)$_SESSION['tenant']['banco_dados'], 'GPT');
if (!UsuarioSessao::atualizar($pdo, $_SESSION)) { http_response_code(401); exit('Sessão expirada.'); }
$permission = PermissaoTransacao::obter('HOMOLOGACAO_FORNECEDOR_FUNCIONARIO');
register_shutdown_function(static function () use ($permission): void { echo '<script>window.greenResponsibilityPermission=' . json_encode(['edit' => !empty($permission['pode_editar']), 'include' => !empty($permission['pode_incluir']), 'delete' => !empty($permission['pode_excluir']),], JSON_UNESCAPED_SLASHES) . ';</script><script src="../assets/js/responsabilidades-permissoes.js?v=3"></script>'; });
if (!$permission['pode_visualizar']) { http_response_code(403); exit('Sem permissão para consultar responsabilidades.'); }
$contextFilters = json_decode((string)($_GET['filtros'] ?? '{}'), true);
if (!is_array($contextFilters)) $contextFilters = [];
$id = filter_input(INPUT_GET, 'CODFUNCIONARIO', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
if (!$id && isset($contextFilters['CODFUNCIONARIO'])) $id = filter_var($contextFilters['CODFUNCIONARIO'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
if (!$id) { http_response_code(400); exit('Funcionário inválido.'); }
$json = static fn(mixed $v): string => json_encode($v, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
$e = static fn(mixed $v): string => htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');
$call = static fn(string $sql, array $params = []): array => GreenPortalDatabase::call($pdo, $sql, $params);
$canMaintain = !empty($permission['pode_visualizar']);
$employee = $call('CALL sp_crud_select(:tabela,:filtros,NULL,1,0)', ['tabela' => 'vw_homologacao_funcionarios_grid', 'filtros' => $json(['CODFUNCIONARIO' => $id])])[0] ?? [];
if (!$employee) { http_response_code(404); exit('Funcionário não localizado.'); }
$types = $call('CALL sp_crud_select(:tabela,:filtros,NULL,100,0)', ['tabela' => 'vw_responsabilidade_tipos', 'filtros' => $json(['MODULO_CODIGO' => 'HOMOLOGACAO', 'ATIVO' => 1])]);
$users = $call('CALL sp_crud_select(:tabela,:filtros,NULL,10000,0)', ['tabela' => 'vw_responsabilidade_usuarios_ativos', 'filtros' => $json([])]);
$groups = $call('CALL sp_crud_select(:tabela,:filtros,NULL,10000,0)', ['tabela' => 'vw_responsabilidade_grupos_ativos', 'filtros' => $json([])]);
$moduleId = (int)($types[0]['CODMODULO'] ?? 0); $message = ''; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'save_rows') {
    if (!$permission['pode_editar'] && !$permission['pode_incluir'] && !$permission['pode_excluir']) { http_response_code(403); exit('Sem permissão para alterar responsabilidades.'); }
    try {
        $ignored = false;
        $existing = $call('CALL sp_crud_select(:tabela,:filtros,NULL,1000,0)', ['tabela' => 'vw_responsabilidade_funcionarios', 'filtros' => $json(['CODFUNCIONARIO' => $id, 'ENTIDADE' => 'fo_funcionarios', 'ATIVO' => 1])]);
        $posted = array_map('strval', array_keys((array)($_POST['rows'] ?? [])));
        if ($permission['pode_excluir']) foreach ($existing as $old) if (!in_array((string)$old['CODATRIBUICAO'], $posted, true)) $call('CALL sp_crud_update(:tabela,:chave,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'chave' => $json(['CODATRIBUICAO' => (int)$old['CODATRIBUICAO']]), 'dados' => $json(['ATIVO' => 0, 'CODUSUARIOALTERACAO' => (int)$_SESSION['usuario']['codusuario']])]);
        foreach ((array)($_POST['rows'] ?? []) as $key => $row) {
            $assignmentId = ctype_digit((string)$key) ? (int)$key : 0;
            if (!empty($row['_delete'])) { if ($assignmentId && $permission['pode_excluir']) $call('CALL sp_crud_update(:tabela,:chave,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'chave' => $json(['CODATRIBUICAO' => $assignmentId]), 'dados' => $json(['ATIVO' => 0, 'CODUSUARIOALTERACAO' => (int)$_SESSION['usuario']['codusuario']])]); continue; }
            if ($assignmentId && !$permission['pode_editar']) {
                $submittedFields = array_diff(array_keys((array)$row), ['_keep', '_delete']);
                if ($submittedFields) $ignored = true;
                continue;
            }
            $typeId = (int)($row['CODTIPORESPONSABILIDADE'] ?? 0); $destination = strtoupper(trim((string)($row['TIPO_DESTINO'] ?? ''))); $userId = $destination === 'USUARIO' ? max(0, (int)($row['CODUSUARIO'] ?? 0)) : null; $groupId = $destination === 'GRUPO' ? max(0, (int)($row['CODGRUPO'] ?? 0)) : null;
            if (!$typeId || !in_array($destination, ['USUARIO', 'GRUPO'], true) || ($destination === 'USUARIO' && !$userId) || ($destination === 'GRUPO' && !$groupId)) throw new RuntimeException('Dados incompletos.');
            $data = ['CODMODULO' => $moduleId, 'ORIGEM' => 'DIRETA', 'CODTIPORESPONSABILIDADE' => $typeId, 'CODCATEGORIARESPONSABILIDADE' => null, 'ENTIDADE' => 'fo_funcionarios', 'REGISTRO_ID' => (string)$id, 'TIPO_DESTINO' => $destination, 'CODUSUARIO' => $userId, 'CODGRUPO' => $groupId, 'PRIORIDADE' => (int)($row['PRIORIDADE'] ?? 0), 'PRINCIPAL' => !empty($row['PRINCIPAL']) ? 1 : 0, 'VALIDO_DE' => trim((string)($row['VALIDO_DE'] ?? '')) ?: date('Y-m-d'), 'VALIDO_ATE' => trim((string)($row['VALIDO_ATE'] ?? '')) ?: null, 'ATIVO' => 1, 'CODUSUARIOALTERACAO' => (int)$_SESSION['usuario']['codusuario']];
            if ($assignmentId) { if ($permission['pode_editar']) $call('CALL sp_crud_update(:tabela,:chave,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'chave' => $json(['CODATRIBUICAO' => $assignmentId]), 'dados' => $json($data)]); else $ignored = true; }
            elseif ($permission['pode_incluir']) $call('CALL sp_crud_insert(:tabela,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'dados' => $json($data)]); else $ignored = true;
        }
        $message = $ignored ? 'Operação concluída. Inclusões e edições não autorizadas foram ignoradas.' : 'Responsabilidades salvas com sucesso.';
    } catch (Throwable $exception) { $error = 'Não foi possível salvar as responsabilidades. Verifique os dados informados.'; }
}
$rows = $call('CALL sp_crud_select(:tabela,:filtros,NULL,1000,0)', ['tabela' => 'vw_responsabilidade_funcionarios', 'filtros' => $json(['CODFUNCIONARIO' => $id, 'ENTIDADE' => 'fo_funcionarios', 'ATIVO' => 1])]);
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Manter responsabilidades</title><link rel="stylesheet" href="../assets/vendor/bootstrap/css/bootstrap.min.css?v=2"><link rel="stylesheet" href="../assets/vendor/bootstrap-icons/bootstrap-icons.css?v=2"><link rel="stylesheet" href="../assets/css/app.css?v=1"><?php require_once dirname(__DIR__) . '/components/pagina_padrao.php'; greenPortalEstiloPagina(); ?></head><body class="p-3 bg-light"><main class="container-fluid"><div class="d-flex justify-content-between align-items-start gap-3 mb-3"><div><h4 class="mb-1"><i class="bi bi-pencil-square me-2"></i>Manter responsabilidades</h4><div class="text-muted small">Funcionário <?= $e($id) ?> — <?= $e($employee['NOME'] ?? '') ?></div></div><a class="btn btn-sm btn-outline-secondary" href="funcionario_responsabilidades.php?CODFUNCIONARIO=<?= $e($id) ?>"><i class="bi bi-eye me-1"></i>Consulta</a></div><?php if ($message): ?><div class="alert alert-success py-2"><?= $e($message) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger py-2"><?= $e($error) ?></div><?php endif; ?><?php if (!$canMaintain): ?><div class="alert alert-warning">Seu perfil não possui permissão para alterar responsabilidades.</div><?php else: ?><form method="post"><input type="hidden" name="action" value="save_rows"><div class="table-responsive border rounded bg-white"><table class="table table-sm align-middle mb-0" id="funcionarioResponsibilityTable"><thead class="table-light"><tr><th>Finalidade</th><th>Destino</th><th>Responsável</th><th>Prioridade</th><th>Principal</th><th>Vigência</th><th></th></tr></thead><tbody><?php foreach ($rows as $row): $key = (int)$row['CODATRIBUICAO']; ?><tr data-row-key="<?= $key ?>"><td><select class="form-select form-select-sm" name="rows[<?= $key ?>][CODTIPORESPONSABILIDADE]"><?php foreach ($types as $type): ?><option value="<?= $e($type['CODTIPORESPONSABILIDADE']) ?>"<?= (string)$type['CODIGO'] === (string)$row['TIPO_CODIGO'] ? ' selected' : '' ?>><?= $e($type['NOME']) ?></option><?php endforeach; ?></select></td><td><select class="form-select form-select-sm js-destination" name="rows[<?= $key ?>][TIPO_DESTINO]"><option value="USUARIO"<?= $row['TIPO_DESTINO'] === 'USUARIO' ? ' selected' : '' ?>>Usuário</option><option value="GRUPO"<?= $row['TIPO_DESTINO'] === 'GRUPO' ? ' selected' : '' ?>>Grupo</option></select></td><td><select class="form-select form-select-sm js-user" name="rows[<?= $key ?>][CODUSUARIO]"><option value="">Selecione</option><?php foreach ($users as $user): ?><option value="<?= $e($user['CODUSUARIO']) ?>"<?= (int)$user['CODUSUARIO'] === (int)$row['CODUSUARIO'] ? ' selected' : '' ?>><?= $e($user['NOME']) ?></option><?php endforeach; ?></select><select class="form-select form-select-sm js-group d-none" name="rows[<?= $key ?>][CODGRUPO]"><option value="">Selecione</option><?php foreach ($groups as $group): ?><option value="<?= $e($group['CODGRUPO']) ?>"<?= (int)$group['CODGRUPO'] === (int)$row['CODGRUPO'] ? ' selected' : '' ?>><?= $e($group['NOME']) ?></option><?php endforeach; ?></select></td><td><input class="form-control form-control-sm" type="number" min="0" name="rows[<?= $key ?>][PRIORIDADE]" value="<?= $e($row['PRIORIDADE']) ?>"></td><td class="text-center"><input type="checkbox" name="rows[<?= $key ?>][PRINCIPAL]" value="1"<?= !empty($row['PRINCIPAL']) ? ' checked' : '' ?>></td><td><div class="d-flex gap-1"><input class="form-control form-control-sm" type="date" name="rows[<?= $key ?>][VALIDO_DE]" value="<?= $e($row['VALIDO_DE']) ?>"><input class="form-control form-control-sm" type="date" name="rows[<?= $key ?>][VALIDO_ATE]" value="<?= $e($row['VALIDO_ATE']) ?>"></div></td><td><button type="button" class="btn btn-sm btn-outline-danger js-delete-row"><i class="bi bi-trash"></i></button></td></tr><?php endforeach; ?></tbody></table></div><div class="d-flex justify-content-between mt-3"><button type="button" class="btn btn-sm btn-outline-primary" id="addFuncionarioResponsibility"><i class="bi bi-plus-lg me-1"></i>Adicionar</button><button type="submit" class="btn btn-sm btn-success"><i class="bi bi-check2 me-1"></i>Salvar</button></div></form><?php endif; ?></main><script>document.addEventListener('DOMContentLoaded',function(){var table=document.querySelector('#funcionarioResponsibilityTable tbody'),types=<?= json_encode($types, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>,users=<?= json_encode($users, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>,groups=<?= json_encode($groups, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>,seq=0;function options(items,id){return '<option value="">Selecione</option>'+items.map(function(x){return '<option value="'+x[id]+'">'+String(x.NOME||'').replace(/</g,'&lt;')+'</option>';}).join('');}function bind(row){row.querySelector('.js-destination').addEventListener('change',function(){var group=this.value==='GRUPO';row.querySelector('.js-user').classList.toggle('d-none',group);row.querySelector('.js-group').classList.toggle('d-none',!group);});row.querySelector('.js-destination').dispatchEvent(new Event('change'));}document.querySelectorAll('#funcionarioResponsibilityTable tr[data-row-key]').forEach(bind);document.querySelector('#addFuncionarioResponsibility')?.addEventListener('click',function(){var key='novo_'+(++seq),row=document.createElement('tr');row.innerHTML='<td><select class="form-select form-select-sm" name="rows['+key+'][CODTIPORESPONSABILIDADE]">'+types.map(function(x){return '<option value="'+x.CODTIPORESPONSABILIDADE+'">'+x.NOME+'</option>';}).join('')+'</select></td><td><select class="form-select form-select-sm js-destination" name="rows['+key+'][TIPO_DESTINO]"><option value="USUARIO">Usuário</option><option value="GRUPO">Grupo</option></select></td><td><select class="form-select form-select-sm js-user" name="rows['+key+'][CODUSUARIO]">'+options(users,'CODUSUARIO')+'</select><select class="form-select form-select-sm js-group d-none" name="rows['+key+'][CODGRUPO]">'+options(groups,'CODGRUPO')+'</select></td><td><input class="form-control form-control-sm" type="number" min="0" name="rows['+key+'][PRIORIDADE]" value="0"></td><td class="text-center"><input type="checkbox" name="rows['+key+'][PRINCIPAL]" value="1"></td><td><div class="d-flex gap-1"><input class="form-control form-control-sm" type="date" name="rows['+key+'][VALIDO_DE]" value="<?= date('Y-m-d') ?>"><input class="form-control form-control-sm" type="date" name="rows['+key+'][VALIDO_ATE]" value=""></div></td><td><button type="button" class="btn btn-sm btn-outline-danger js-delete-row"><i class="bi bi-trash"></i></button></td>';table.appendChild(row);bind(row);});});</script></body></html>
